('127.351.d.11.C',3,'A lineman who works on power lines typically needs:','["no training", "only a hobby", "a technical training program and certification", "a pastry license"]'::jsonb,2,'Technical training is required.','original'),
('127.351.d.11.C',4,'Petroleum engineers usually need:','["a cooking certificate", "a cosmetology license", "no education", "a bachelor''s degree in engineering"]'::jsonb,3,'Engineering roles require a degree.','original'),
