('127.356.d.5.F',3,'Estimating a measurement before calculating helps a technician:','["lose data", "avoid math", "waste time", "check that the final answer is reasonable"]'::jsonb,3,'Estimates catch errors.','original'),
('127.356.d.5.F',4,'A tank holds about 1,000 gallons and the pump moves 50 gallons per minute. The time to fill is about:','["20 minutes", "500 minutes", "5 minutes", "50 minutes"]'::jsonb,0,'1,000 / 50 = 20.','original'),
('127.356.d.5.G',3,'The number 4,500,000 written in scientific notation is:','["4.5 x 10^5", "4.5 x 10^6", "45 x 10^5", "0.45 x 10^6 only"]'::jsonb,1,'Move the decimal six places.','original'),
('127.356.d.5.G',4,'In the metric system, one kilometer equals:','["10,000 meters", "10 meters", "1,000 meters", "100 meters"]'::jsonb,2,'Kilo means thousand.','original'),
('127.356.d.5.H',3,'Plotting readings from a gauge over time on a graph shows:','["stories", "jokes", "names", "trends"]'::jsonb,3,'Graphs reveal patterns.','original'),
